script.text:

function active$Form$(f) {
	f.add_onResponseComplete(on$Form$ResponseComplete);
	f.add_commandEvent(on$Form$ExecuteCommand);[#TabControl#]			
	f._tabContainer.add_activeTabChanged(onChange$Form$Tab);
	f._tabContainer._loaded = true;[#TabControl#]	
	[#Comment#]&PostCreate;[#Comment#]			
}

function close$Form$(f) {
		try {f.remove_commandEvent(on$Form$ExecuteCommand);} catch (ex) {}
		try {f.remove_onResponseComplete(on$Form$ResponseComplete);} catch (ex) {}[#TabControl#]
		if (f._tabContainer) try {f._tabContainer.remove_activeTabChanged(onChange$Form$Tab);} catch (ex) {}[#TabControl#]							 
		[#Comment#]&PostDispose;[#Comment#]
}

function on$Form$ExecuteCommand(sender, e) {
var action = e.type.Action, f = sender;
switch (action) {				
		[#Comment#]case 'Shown':						 
				&PostShown; 
				break; 
		case 'Gather':
			var g = f.getItem('dmdemo_detail')._controlBehavior;
			g.setSequenceNumber('line_nbr');
				break;[#Comment#]
		default:
				break;
		}
}
function on$Form$ResponseComplete(sender, e) {
		var f = e.object, context = e.type.Context, result = e.type.Result;
		switch (context){ 
			[#Comment#]case 'Scattering':
				&PostScattering;
				break;
			case 'Navigating':
				&PostRefresh;
				break;[#Comment#]
			default:
				break;
		}
	}
[#TabControl#]function onChange$Form$Tab(sender, e) {
		sender.parentForm.focusWhenTabChanged([#FOCUSTAB#]);				
		[#Comment#]&PostTabFocus;[#Comment#] 
}[#TabControl#]


[#Comment#]&PostScript;[#Comment#]
